<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { operations, errorText, money, dateTime, type SchoolOverview } from '../../lib/operations';
import AppIcon from '../../ui/AppIcon.vue';
import AppSelect from '../../ui/AppSelect.vue';
import SchoolCreateDialog from './SchoolCreateDialog.vue';
const route = useRoute();
const router = useRouter();
const q = ref('');
const status = ref(String(route.query.status || ''));
const schools = ref<SchoolOverview[]>([]);
const loading = ref(false);
const error = ref('');
const creating = ref(false);
let requestId = 0;
const filtered = computed(() => !!q.value.trim() || !!status.value);
const statuses = [{ value: '', label: '全部服务状态' }, { value: 'active', label: '服务中' }, { value: 'inactive', label: '已停用' }];
async function load() { const id = ++requestId; loading.value = true; error.value = ''; try { const result = await operations.schools(q.value.trim(), status.value); if (id === requestId) schools.value = result; } catch (e) { if (id === requestId) error.value = errorText(e, '学校列表暂时无法加载'); } finally { if (id === requestId) loading.value = false; } }
function reset() { q.value = ''; status.value = ''; load(); }
function created(id: number) { creating.value = false; router.push(`/ops/schools/${id}`); }
onMounted(load);
</script>
<template>
  <div>
    <div class="page-heading"><div><h1 class="page-title">学校管理</h1><p class="page-description">建立学校空间，交付管理账号，持续关注学校服务。</p></div><button class="btn btn-primary" @click="creating = true"><AppIcon name="plus" :size="17" />开通学校</button></div>
    <section class="schools-intro"><span class="icon-tile icon-tile-mint"><AppIcon name="school" :size="25" /></span><div><h2>每所学校，拥有独立的服务空间</h2><p>学校管理员负责本校师生、课程、报名与费用；运营统一管理学校开通与账号交付。</p></div><span class="intro-label"><AppIcon name="shield" :size="15" />学校数据独立</span></section>
    <section class="card"><form class="schools-toolbar" @submit.prevent="load"><div class="search-field"><AppIcon name="search" :size="18" /><label class="sr-only" for="school-search">搜索学校</label><input id="school-search" v-model="q" placeholder="搜索学校名称、编码或联系人" maxlength="80" /></div><div class="status-filter"><AppSelect v-model="status" :options="statuses" :disabled="loading" @update:model-value="load" /></div><button class="btn btn-secondary" :disabled="loading" type="submit">{{ loading ? '查询中…' : '查询' }}</button><button v-if="filtered" class="btn btn-ghost" type="button" :disabled="loading" @click="reset">重置</button><span class="result-count">{{ loading ? '正在读取学校' : `共 ${schools.length} 所学校` }}</span></form>
    <div v-if="error" class="school-state" role="alert"><span class="icon-tile icon-tile-rose"><AppIcon name="alert" :size="24" /></span><h3>学校列表暂时无法加载</h3><p>{{ error }}</p><button class="btn btn-secondary mt-4" @click="load">重新加载</button></div><div v-else-if="loading" class="school-state" role="status"><AppIcon class="text-brand" name="school" :size="30" /><p>正在读取学校服务数据…</p></div><div v-else-if="!schools.length" class="school-state"><span class="icon-tile icon-tile-blue"><AppIcon :name="filtered ? 'search' : 'school'" :size="25" /></span><h3>{{ filtered ? '没有找到匹配的学校' : '还没有开通学校' }}</h3><p>{{ filtered ? '试试其他关键词，或清空筛选条件。' : '创建学校空间和首位管理员，即可开始交付。' }}</p><button class="btn btn-secondary mt-4" @click="filtered ? reset() : creating = true">{{ filtered ? '清空筛选' : '开通第一所学校' }}</button></div>
    <template v-else><div class="schools-table overflow-x-auto"><table class="table-base min-w-[980px]"><thead><tr><th>学校 / 当前学期</th><th>服务状态</th><th>学校规模</th><th>管理员</th><th>待收费用</th><th>学校联系人</th><th></th></tr></thead><tbody><tr v-for="school in schools" :key="school.id"><td><router-link :to="`/ops/schools/${school.id}`" class="table-school"><span class="school-initial">{{ school.name.slice(0, 1) }}</span><div><strong>{{ school.name }}</strong><p>{{ school.term }}</p><small>{{ school.code }} · {{ dateTime(school.createdAt) }} 开通</small></div></router-link></td><td><span class="badge" :class="school.status === 'active' ? 'badge-green' : 'badge-gray'">{{ school.status === 'active' ? '服务中' : '已停用' }}</span></td><td><div class="text-[12px]">{{ school.stats.students }} 名学生</div><p class="mt-1 text-[10px] text-ink-3">{{ school.stats.teachers }} 名教师 · {{ school.stats.courses }} 门课程</p></td><td><span class="text-[13px]">{{ school.stats.admins }} 人</span></td><td><strong class="amount">{{ money(school.stats.outstanding) }}</strong></td><td><div class="text-[12px]">{{ school.contactName || '未填写' }}</div><p class="mt-1 text-[11px] text-ink-3">{{ school.contactPhone || '—' }}</p></td><td><router-link :to="`/ops/schools/${school.id}`" class="btn btn-ghost btn-sm text-brand">管理<AppIcon name="chevron-right" :size="15" /></router-link></td></tr></tbody></table></div>
    <div class="school-cards"><router-link v-for="school in schools" :key="school.id" :to="`/ops/schools/${school.id}`" class="school-card"><div class="flex items-center gap-3"><span class="school-initial">{{ school.name.slice(0, 1) }}</span><div class="min-w-0 flex-1"><h3>{{ school.name }}</h3><p>{{ school.term }}</p></div><span class="badge" :class="school.status === 'active' ? 'badge-green' : 'badge-gray'">{{ school.status === 'active' ? '服务中' : '已停用' }}</span></div><div class="mobile-stats"><div><strong>{{ school.stats.students }}</strong><span>学生</span></div><div><strong>{{ school.stats.teachers }}</strong><span>教师</span></div><div><strong>{{ school.stats.courses }}</strong><span>课程</span></div><div><strong>{{ school.stats.admins }}</strong><span>管理员</span></div></div><div class="mobile-school-footer"><span>待收 <strong>{{ money(school.stats.outstanding) }}</strong></span><span class="flex items-center gap-1 text-brand">管理学校<AppIcon name="arrow-right" :size="15" /></span></div></router-link></div><div class="schools-footer"><AppIcon name="info" :size="14" />停用学校会保留资料与账单，并暂停该校成员登录及业务访问。</div></template></section>
    <SchoolCreateDialog :show="creating" @close="creating = false" @created="created" />
  </div>
</template>
<style scoped>
