-align:center}.school-state h3{margin-top:15px;font-size:15px;font-weight:600}.school-state p{margin-top:8px;font-size:12px;line-height:1.8;color:var(--color-ink-3)}.school-cards{display:none}@media(max-width:1150px){.intro-label{display:none}.schools-toolbar{flex-wrap:wrap}.search-field{flex:1;min-width:210px}.result-count{width:100%;margin:3px 0 0}}@media(max-width:650px){.schools-intro{align-items:flex-start;padding:19px}.schools-intro .icon-tile{display:none}.schools-intro h2{font-size:13px}.schools-toolbar{gap:9px;padding:16px}.search-field{width:100%;max-width:none;flex-basis:100%;min-width:0}.status-filter{flex:1;width:auto}.schools-toolbar>.btn{font-size:12px;padding:0 12px}.result-count{font-size:10px}.schools-table{display:none}.school-cards{display:block;padding:0 16px}.school-card{display:block;padding:20px 0;border-bottom:1px solid var(--color-line);text-decoration:none;color:var(--color-ink)}.school-card:last-child{border:0}.school-card h3{font-size:13px;font-weight:600}.school-card p{margin-top:3px;font-size:11px;color:var(--color-ink-3)}.school-card .badge{font-size:10px}.mobile-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:17px 0;padding:13px 0;border-radius:10px;background:#f8f9fc}.mobile-stats>div{text-align:center;border-right:1px solid var(--color-line)}.mobile-stats>div:last-child{border:0}.mobile-stats strong{display:block;font-size:17px;font-weight:600}.mobile-stats span{font-size:10px;color:var(--color-ink-3)}.mobile-school-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;color:var(--color-ink-3)}.mobile-school-footer strong{margin-left:5px;color:var(--color-ink);font-weight:600}.schools-footer{align-items:flex-start;padding:14px 16px}.schools-footer>svg{margin-top:3px}}
